using System;using System.Linq;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class CheckTree162{
 [Serializable]public class Routes{public Vector3[] a,b,c;}
 public static string Main(){var s=SceneManager.GetSceneByPath("Assets/Scenes/TreeHouseVariantsWorkshop.unity");var roots=s.GetRootGameObjects().Where(r=>r.name.StartsWith("0")&&!r.name.StartsWith("00")).OrderBy(r=>r.name).ToArray();
 var routes=JsonUtility.FromJson<Routes>(File.ReadAllText("Temp/tree-routes162.json"));routes.b[3]=roots[1].transform.TransformPoint(new Vector3(-4,4.9f,-4.5f));routes.c[3]=roots[2].transform.TransformPoint(new Vector3(1.6f,4.9f,-4));routes.b=new[]{new Vector3(27,.3f,-22.7f),new Vector3(27,2.6f,-13.5f),new Vector3(32,2.6f,-13.5f),new Vector3(32,4.9f,-4.5f)};var all=new[]{routes.a,routes.b,routes.c};var log=new System.Text.StringBuilder();
 for(int index=0;index<3;index++){var obj=new GameObject("Climb_Probe");SceneManager.MoveGameObjectToScene(obj,s);obj.transform.position=all[index][0];var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Player.prefab").GetComponent<CharacterController>();var cc=obj.AddComponent<CharacterController>();cc.height=source.height;cc.radius=source.radius;cc.center=source.center;cc.stepOffset=source.stepOffset;cc.skinWidth=source.skinWidth;cc.slopeLimit=source.slopeLimit;Physics.SyncTransforms();foreach(var goal in all[index].Skip(1)){for(int j=0;j<1500;j++){var delta=goal-obj.transform.position;delta.y=0;if(delta.magnitude<.12f)break;cc.Move(delta.normalized*.04f+Vector3.down*.025f);}}log.AppendLine(roots[index].name+" pos="+obj.transform.position+": reached y="+obj.transform.position.y+" target="+all[index].Last().y);if(obj.transform.position.y<4.5f)log.AppendLine("FAIL ascent");UnityEngine.Object.DestroyImmediate(obj);PrefabUtility.SaveAsPrefabAsset(roots[index],"Assets/Prefabs/Workshop/TreeHousePrototypes/"+roots[index].name+".prefab");}
 EditorSceneManager.SaveScene(s);var camera=s.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Camera>()).First();var rt=RenderTexture.GetTemporary(1800,1000,24);var old=RenderTexture.active;try{camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var tex=new Texture2D(1800,1000);tex.ReadPixels(new Rect(0,0,1800,1000),0,0);Directory.CreateDirectory("Docs/locations/previews");File.WriteAllBytes("Docs/locations/previews/treehouse-prototypes162.png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{camera.targetTexture=null;RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);}return log.ToString();}
}

